'use client';

import { listenToProjectMoneyRaised } from 'lib/firebase/project-money-raised-listener';
import { FC, useEffect, useState } from 'react';
import { FinanceAndAnalysis } from './finance-and-analysis/FinanceAndAnalysis';
import { Header } from './Header';
import { LatestUpdate } from './latest-updates/LatestUpdate';
import { ProjectDetails } from './project-details/ProjectDetails';
import { Raised } from './Raised';
import { Tabs } from './Tabs';

export const SingleProjectPage: FC<{ project: Project }> = ({ project }) => {
  const [activeTab, setActiveTab] = useState<'details' | 'finance' | 'updates'>(
    'details',
  );
  const [moneyRaised, setMoneyRaised] = useState<number>(
    project.moneyRaised ?? 0,
  );

  useEffect(() => {
    if (!project?.id) return;
    const unsubscribe = listenToProjectMoneyRaised(project.id, setMoneyRaised);
    return unsubscribe;
  }, [project?.id]);

  const renderContent = () => {
    switch (activeTab) {
      case 'details':
        return <ProjectDetails project={project} />;
      case 'finance':
        return <FinanceAndAnalysis project={project} />;
      case 'updates':
        return <LatestUpdate project={project} />;
    }
  };

  return (
    <main className="p-20 lg:p-40 bg-off-white w-full h-full">
      <Header project={project} />
      <Tabs activeTab={activeTab} onTabChange={setActiveTab} />
      <div className="flex flex-col lg:flex-row gap-32 relative">
        {renderContent()}
        <Raised project={project} moneyRaised={moneyRaised} />
      </div>
    </main>
  );
};

