  description: string;
  date: number;
}

interface FinancialDocument {
  name: string;
  url: string;
}

interface PressLink {
  url: string;
  headline: string;
  source: string;
  imageUrl?: string;
}

interface MediaLink {
  url: string;
  platform: 'instagram' | 'twitter' | 'facebook' | 'tiktok' | 'youtube' | 'other';
  caption: string;
  imageUrl?: string;
  date?: number;
}

type ProjectType = 'theatre' | 'film' | 'tv' | 'music';

type ProjectStatus =
  | 'closed'
  | 'in-production'
  | 'fundraising'
  | 'active'
  | 'fully-funded';

