import { AuthAtoms } from '@modules/auth/jotai/atoms';
import { InvestModal } from '@modules/dashboard/components/invest-modal';
import { Button } from '@modules/shared/button';
import { formatPrice } from '@modules/shared/utils/formatPrice';
import { format } from 'date-fns/format';
import { useAtomValue } from 'jotai';
import {
  getWaitlistEntry,
  joinWaitlist,
  leaveWaitlist,
} from 'lib/firebase/waitlist-actions';
import { cn } from 'lib/utils';
import { Clock } from 'lucide-react';
import Image from 'next/image';
import { FC, useEffect, useState } from 'react';
import { toast } from 'sonner';

const PRESET_AMOUNTS = [5000, 10000, 25000, 50000, 100000, 250000];

export const Raised: FC<{ project: Project; moneyRaised: number }> = ({
  project,
  moneyRaised,
}) => {
  const { fundraisingEndDate } = project;
  const firestoreUser = useAtomValue(AuthAtoms.user);
  const [investAmount, setInvestAmount] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [waitlistAmount, setWaitlistAmount] = useState(0);
  const [waitlistEntry, setWaitlistEntry] = useState<WaitlistEntry | null>(
    null,
  );
  const [waitlistLoading, setWaitlistLoading] = useState(false);
  const endDate = fundraisingEndDate < new Date().getTime();
  const progressPct =
    project.financials.targetInvestment > 0
      ? Math.min((moneyRaised / project.financials.targetInvestment) * 100, 100)
      : 0;

  useEffect(() => {
    if (!firestoreUser || !endDate) return;
    getWaitlistEntry(firestoreUser.uid, project.id).then(setWaitlistEntry);
  }, [firestoreUser, project.id, endDate]);

  useEffect(() => {
    if (!isModalOpen) setInvestAmount(0);
  }, [isModalOpen]);

  const handleInvestClick = () => {
    setIsModalOpen(true);
  };

  const handleWaitlist = async () => {
    try {
      if (!firestoreUser) return;
      setWaitlistLoading(true);

      if (waitlistEntry) {
        await leaveWaitlist(firestoreUser.uid, project.id);
        setWaitlistEntry(null);
        setWaitlistAmount(0);
        toast.success('Removed from waitlist');
        return;
      }

      const entry: WaitlistEntry = {
        projectId: project.id,
        projectName: project.name,
        userId: firestoreUser.uid,
        userEmail: firestoreUser.email,
        amount: waitlistAmount,
        date: Date.now(),
      };
      await joinWaitlist(entry);
      setWaitlistEntry(entry);
      toast.success("You're on the waitlist!");
    } catch (error) {
      console.error('Error updating waitlist:', error);
      toast.error('Failed to update waitlist');
    } finally {
      setWaitlistLoading(false);
    }
  };

  return (
    <div className="max-lg:-order-1 lg:sticky lg:top-24 p-24 bg-dark-blue rounded-[16px] lg:w-2/5 w-full h-max text-white flex flex-col">
      <span className="text-[clamp(24px,48px)] leading-[140%]] font-family-tiempos font-light">
        {formatPrice(moneyRaised)}{' '}
        <span className="text-[clamp(16px,24px)] leading-[140%]">raised</span>
      </span>
      <span className="text-tiny font-semibold mb-16">
        of {formatPrice(project.financials.targetInvestment)} Funding Goal Total
      </span>
      <div className="w-full h-16 bg-gray-100 rounded-full overflow-hidden mb-16">
        <div
          className="h-full bg-primary flex items-center justify-end pr-8 rounded-full"
          style={{
            width: `${progressPct}%`,
          }}
        />
      </div>
      <p className="flex items-center gap-4 text-[9px] mb-8">
        <Clock width={12} height={12} />
        Investing deadline {format(fundraisingEndDate, 'MMM d, yyyy')}
      </p>
      <p className="flex items-start gap-4 text-[9px] mb-32">
        <Image
          src="/images/i.png"
          alt="Info"
          width={24}
          height={44}
          className="shrink-0 h-16 w-auto"
        />
        The total funding goal reflects the Beni Capital investment allocation
        into the Total Capitalization
      </p>
      <div className="pt-32 border-t border-white/50">
        {endDate ? (
          <>
            <p className="text-[clamp(16px,22px)] leading-[100%] font-semibold mb-8">
              {waitlistEntry ? 'You are on the waitlist' : 'Funding Closed'}
            </p>
            {waitlistEntry ? (
              <p className="text-tiny text-gray-2 mb-16">
                Your intended investment of{' '}
                <span className="text-white font-medium">
                  {formatPrice(waitlistEntry.amount)}
                </span>{' '}
                has been registered. We&apos;ll reach out if a spot opens up.
              </p>
            ) : (
              <p className="text-tiny text-gray-2 mb-16">
                This project&apos;s fundraising period has ended. Join the
                waitlist with your intended investment amount to be notified if
                a spot opens up.
              </p>
            )}
            {!waitlistEntry && (
              <div className="grid grid-cols-2 xsm:grid-cols-3 gap-8 mb-16">
                {PRESET_AMOUNTS.map((amount) => (
                  <button
                    key={amount}
                    onClick={() => setWaitlistAmount(amount)}
                    disabled={waitlistLoading}
                    className={cn(
                      'cursor-pointer rounded-[12px] py-10 px-8 text-tiny font-medium border transition-all duration-200',
                      waitlistAmount === amount
                        ? 'bg-primary border-primary text-white'
                        : 'bg-white/10 border-white/20 text-white hover:bg-white/20',
                      waitlistLoading && 'opacity-50 cursor-not-allowed',
                    )}>
                    {formatPrice(amount)}
                  </button>
                ))}
              </div>
            )}
            <Button
              size="large"
              disabled={
                waitlistLoading ||
                !firestoreUser ||
                (!waitlistEntry && !waitlistAmount)
              }
              onClick={handleWaitlist}
              variant={waitlistEntry ? 'outline' : 'default'}
              className="w-full rounded-[16px]">
              {waitlistEntry ? 'Leave Waitlist' : 'Join Waitlist'}
            </Button>
          </>
        ) : (
          <>
            <p className="text-[clamp(16px,22px)] leading-[100%] font-semibold mb-16">
              Become a Beni-factor
            </p>
            <div className="grid grid-cols-2 xsm:grid-cols-3 gap-8 mb-16">
              {PRESET_AMOUNTS.map((amount) => (
                <button
                  key={amount}
                  onClick={() => setInvestAmount(amount)}
                  className={cn(
                    'cursor-pointer rounded-[12px] py-10 px-8 text-tiny font-medium border transition-all duration-200',
                    investAmount === amount
                      ? 'bg-primary border-primary text-white'
                      : 'bg-white/10 border-white/20 text-white hover:bg-white/20',
                  )}>
                  {formatPrice(amount)}
                </button>
              ))}
            </div>
            <p className="text-tiny text-gray-2 mb-8">
              Applicable taxes and fees will be added to your total at the time
              of processing.
            </p>
            <Button
              size="large"
              disabled={!investAmount}
              onClick={handleInvestClick}
              className="w-full rounded-[16px]">
              Invest
            </Button>
          </>
        )}
      </div>

      <InvestModal
        open={isModalOpen}
        onOpenChange={setIsModalOpen}
        project={project}
        initialAmount={investAmount}
      />
    </div>
  );
};

'use client';

import { Button } from '@modules/shared/button';
import { formatPrice } from '@modules/shared/utils/formatPrice';
import { Routes } from 'const/Routes';
import { CheckCircle2 } from 'lucide-react';
import Link from 'next/link';
import { useRouter, useSearchParams } from 'next/navigation';
import { FC } from 'react';

export const InvestmentSuccess: FC = () => {
  const searchParams = useSearchParams();
  const router = useRouter();

  const projectName = searchParams.get('projectName');
  const amount = searchParams.get('amount');
  const projectId = searchParams.get('projectId');

  // Redirect if required params are missing
  if (!projectName || !amount) {
    router.push(Routes.DISCOVER_PROJECTS);
    return null;
  }

  return (
    <main className="p-20 lg:p-40 bg-off-white w-full min-h-screen flex items-center justify-center">
      <div className="max-w-[600px] w-full bg-white rounded-[24px] p-40 flex flex-col items-center text-center shadow-lg">
        <div className="w-80 h-80 rounded-full bg-green-100 flex items-center justify-center mb-24">
          <CheckCircle2 className="w-48 h-48 text-green-600" />
        </div>

        <h1 className="font-family-tiempos text-[clamp(32px,48px)] leading-[140%] font-light mb-16">
          Congratulations!
        </h1>

        <p className="text-[clamp(18px,24px)] text-gray-700 mb-32">
          Your investment was successful
        </p>

        <div className="w-full p-32 bg-off-white rounded-[16px] mb-32">
          <div className="flex flex-col gap-16">
            <div className="flex justify-between items-center">
              <span className="text-gray-600">Project</span>
              <span className="font-semibold text-right">{projectName}</span>
            </div>
            <div className="w-full h-[1px] bg-gray-200" />
            <div className="flex justify-between items-center">
              <span className="text-gray-600">Investment Amount</span>
              <span className="font-semibold text-[clamp(20px,24px)] text-green-600">
                {formatPrice(Number(amount))}
              </span>
            </div>
          </div>
        </div>

        <p className="text-gray-600 mb-32 text-small">
          You can track your investment progress in the My Investments section.
          We'll send you updates about {projectName} as the project develops.
        </p>

        <div className="flex flex-col xsm:flex-row gap-16 w-full">
          {projectId && (
            <Link
              href={`${Routes.DISCOVER_PROJECTS}/${projectId}`}
              className="flex-1">
              <Button variant="outline" size="large" className="w-full">
                View Project
              </Button>
            </Link>
          )}
          <Link href={Routes.MY_INVESTMENTS} className="flex-1">
            <Button size="large" className="w-full">
              My Investments
            </Button>
          </Link>
        </div>
      </div>
    </main>
  );
};

export enum Routes {
  HOME = '/',
  OVERVIEW = '/overview',
  FEES = '/fees',
  APPLY_HERE = '/apply-here',
  SUBMIT_PROJECT = '/submit-project',
  CONTACT_US = '/contact-us',
  LOGIN = '/login',
  APPLY = '/apply',
  PRICING = '/pricing',
  OUR_TEAM = '/our-team',
  FAQ = '/faq',
  SIGN_UP = '/sign-up',
  DASHBOARD = '/dashboard',
  TERMS_OF_SERVICE = '/terms-of-service',
  PRIVACY_POLICY = '/privacy-policy',
  DISCLAIMER = '/disclaimer',
  DISCOVER_PROJECTS = '/dashboard/discover-projects',
  MY_INVESTMENTS = '/dashboard/my-investments',
  FAVORITES = '/dashboard/favorites',
  PROJECT_DETAILS = 'PROJECT_DETAILS',
  RESET_PASSWORD = '/reset-password',
  ADMIN_PROJECT_LIST = '/dashboard/admin/projects',
  INVESTMENT_SUCCESS = '/dashboard/investment-success',
}

export const ROUTES_LIST = [
  {
    label: 'Overview',
    href: `${Routes.HOME}#overview`,
  },
  {
    label: 'Apply Here',
    href: Routes.APPLY_HERE,
  },
  {
    label: 'FAQ',
    href: Routes.FAQ,
  },
  {
    label: 'Contact Us',
    href: Routes.CONTACT_US,
  },
  {
    label: 'Login',
    href: Routes.LOGIN,
  },
  {
    label: 'Apply for Access',
    href: Routes.APPLY,
  },
];

