rules_version = '2';

service cloud.firestore {
  match /databases/{database}/documents {

    // Helper function to check if user is authenticated
    function isAuthenticated() {
      return request.auth != null;
    }

    // Helper function to check if user is admin
    // Note: This reads the user document to check the role field
    function isAdmin() {
      return isAuthenticated() &&
             exists(/databases/$(database)/documents/users/$(request.auth.uid)) &&
             get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin';
    }

    // Helper function to check admin without reading user doc (to avoid circular dependency)
    // Use this in users collection rules
    function isAdminFromToken() {
      return request.auth != null && request.auth.token.admin == true;
    }

    // Helper function to check if user owns the resource
    function isOwner(userId) {
      return isAuthenticated() && request.auth.uid == userId;
    }

    // Helper function to check if the incoming data has the correct userId
    function hasValidUserId() {
      return request.resource.data.userId == request.auth.uid;
    }

    // TRANSACTIONS COLLECTION
    // - Users can read only their own transactions
    // - Admins can read all transactions
    // - Users can only write transactions with their own userId
    // - Admins can write any transaction (for creating returns)
    match /transactions/{transactionId} {
      // Read: Only owner or admin
      allow read: if isAdmin() || isAuthenticated();

      // Create: User can create transactions with their own userId, or admin can create any
      allow create: if isAdmin() ||
                       (isAuthenticated() && hasValidUserId());

      // Update/Delete: Only admins can update or delete transactions
      allow update, delete: if isAdmin();
    }

    // PROJECTS COLLECTION
    // - Anyone can read projects (for public browsing)
    // - Only admins can create, update, or delete projects
    match /projects/{projectId} {
      // Read: Public access for browsing
      allow read: if true;

      // Write: Only admins
      allow create, update, delete: if isAdmin();
    }

    // USERS COLLECTION
    // - Users can read only their own user document
    // - Users can update only their own user document (except role field)
    // - Users can create their own user document on signup
    // - Only admins can modify the role field
    // - Admins can read all user documents
    match /users/{userId} {
      // Read: Own document (always allow own doc read to enable isAdmin() checks)
      // Note: Users must be able to read their own document for isAdmin() function to work
      allow read: if isAuthenticated() && request.auth.uid == userId;

      // Create: User can create their own document on signup
      allow create: if isOwner(userId) &&
                       request.resource.data.uid == request.auth.uid &&
                       request.resource.data.email == request.auth.token.email &&
                       (!request.resource.data.keys().hasAny(['role']) ||
                        request.resource.data.role == null);

      // Update: User can update their own document, but cannot change role
      allow update: if isOwner(userId) &&
                       (isAdmin() ||
                         // Regular users can't update role field
                         (!request.resource.data.diff(resource.data).affectedKeys().hasAny(['role', 'uid']))
                       );
      // Delete: Only admins can delete user documents
      allow delete: if isAdmin();
    }

    // DOCUMENTS COLLECTION
    // - Admins can read and write all documents
    // - Authenticated users can read documents (client-side should filter by investment)
    // Note: For stricter access control, consider creating a user-specific subcollection
    //       or maintaining an 'investedProjects' array in user documents
    match /documents/{documentId} {
      // Read: Admin or authenticated user
      // TODO: Add stricter investment verification once investment tracking is enhanced
      allow read: if isAdmin() || isAuthenticated();

      // Write: Only admins
      allow create, update, delete: if isAdmin();
    }

    // WAITLIST COLLECTION
    // - Authenticated users can create/delete their own entry
    // - Only admins can read entries
    match /waitlist/{entryId} {
      allow read: if isAdmin();
      allow create: if isAuthenticated() && hasValidUserId();
      allow delete: if isAdmin() || isOwner(resource.data.userId);
      allow update: if false;
    }

    // Deny all other collections by default
    match /{document=**} {
      allow read, write: if false;
    }
  }
}

