'use server';

import { Routes } from 'const/Routes';
import { createEmbeddedCheckout } from 'lib/easy-api/checkout';
import { headers } from 'next/headers';

export type CreateCheckoutInput = {
  priceId: string;
  amount: number;
  userId: string;
  userEmail: string;
  projectId: string;
  projectName: string;
  projectType: ProjectType;
};

export async function createCheckoutAction(
  input: CreateCheckoutInput,
): Promise<string> {
  const { priceId, amount, userId, userEmail, projectId, projectName, projectType } = input;

  const headersList = await headers();
  const host = headersList.get('host') ?? 'localhost:3000';
  const protocol = host.includes('localhost') ? 'http' : 'https';
  const baseUrl = `${protocol}://${host}`;

  const result = await createEmbeddedCheckout({
    line_items: [{ price_id: priceId, quantity: 1 }],
    mode: 'payment',
    success_url: `${baseUrl}${Routes.INVESTMENT_SUCCESS}?session_id={SESSION_ID}&projectId=${encodeURIComponent(projectId)}&projectName=${encodeURIComponent(projectName)}&amount=${amount}`,
    cancel_url: `${baseUrl}${Routes.INVESTMENT_CANCELLED}?projectId=${encodeURIComponent(projectId)}&projectName=${encodeURIComponent(projectName)}`,
    customer_email: userEmail,
    metadata: {
      userId,
      userEmail,
      projectId,
      projectName,
      projectType,
      amount: String(amount),
    },
  });

  if (!result.ok) {
    throw new Error('Failed to create checkout session. Please try again.');
  }

  return result.data.url;
}

