import { adminDb } from 'lib/firebase/admin';
import { NextResponse } from 'next/server';

// Easy API webhook event payload shape for embedded checkout completion
type EasyApiWebhookEvent = {
  type: string;
  data: {
    id: string;
    status: string;
    amount_total: number;
    currency: string;
    customer_email?: string;
    metadata?: {
      userId?: string;
      userEmail?: string;
      projectId?: string;
      projectName?: string;
      projectType?: string;
      amount?: string;
    };
  };
};

export async function POST(request: Request) {
  let event: EasyApiWebhookEvent;

  try {
    event = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }

  // Only process completed checkout sessions
  if (event?.data?.status !== 'complete') {
    return NextResponse.json({ received: true });
  }

  const { metadata, id: sessionId } = event.data;

  if (!metadata?.userId || !metadata?.projectId || !metadata?.amount) {
    return NextResponse.json(
      { error: 'Missing required metadata fields: userId, projectId, amount' },
      { status: 400 },
    );
  }

  const amount = Number(metadata.amount);
  const projectType = (metadata.projectType ?? 'film') as ProjectType;

  const transaction: Transaction = {
    type: 'investment',
    projectId: metadata.projectId,
    projectName: metadata.projectName ?? '',
    projectType,
    amount,
    date: Date.now(),
    userId: metadata.userId,
    userEmail: metadata.userEmail ?? '',
    paymentId: sessionId,
  };

  await adminDb.collection('transactions').add(transaction);

  // Update project's moneyRaised counter
  const projectRef = adminDb.collection('projects').doc(metadata.projectId);
  await projectRef.update({
    moneyRaised: (await projectRef.get()).data()?.moneyRaised
      ? (await projectRef.get()).data()!.moneyRaised + amount
      : amount,
  });

  return NextResponse.json({ received: true });
}

