'use client';

import { AuthAtoms } from '@modules/auth/jotai/atoms';
import { Button } from '@modules/shared/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@modules/shared/dialog';
import { Label } from '@modules/shared/label';
import { formatPrice } from '@modules/shared/utils/formatPrice';
import { createCheckoutAction } from 'modules/easy-api/actions/create-checkout';
import { useAtomValue } from 'jotai';
import { cn } from 'lib/utils';
import { useRouter } from 'next/navigation';
import { FC, useEffect, useState } from 'react';
import { toast } from 'sonner';

const PRESET_AMOUNTS = [5000, 10000, 25000, 50000, 100000, 250000];

interface InvestModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  project: Project;
  initialAmount?: number;
}

export const InvestModal: FC<InvestModalProps> = ({
  open,
  onOpenChange,
  project,
  initialAmount = 0,
}) => {
  const firestoreUser = useAtomValue(AuthAtoms.user);
  const router = useRouter();
  const [amount, setAmount] = useState(initialAmount);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (open && initialAmount > 0) setAmount(initialAmount);
  }, [open, initialAmount]);

  const handleInvest = async () => {
    if (!firestoreUser) {
      toast.error('You must be logged in to invest');
      return;
    }

    if (!amount) {
      toast.error(
        `Minimum investment is ${formatPrice(project.financials.minInvestment)}`,
      );
      return;
    }

    const priceId = project.easyApiPriceIds?.[String(amount)];
    if (!priceId) {
      toast.error(
        'Checkout is not available for this amount. Please contact support.',
      );
      return;
    }

    try {
      setLoading(true);
      const checkoutUrl = await createCheckoutAction({
        priceId,
        amount,
        userId: firestoreUser.uid,
        userEmail: firestoreUser.email ?? '',
        projectId: project.id,
        projectName: project.name,
        projectType: project.type,
      });
      router.push(checkoutUrl);
    } catch (error) {
      console.error('Checkout error:', error);
      toast.error('Failed to start checkout. Please try again.');
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px] bg-dark-blue text-white">
        <DialogHeader>
          <DialogTitle className="font-family-tiempos text-[24px] font-light">
            Invest in {project.name}
          </DialogTitle>
          <DialogDescription className="text-gray-2">
            Select your investment amount. Minimum:{' '}
            {formatPrice(project.financials.minInvestment)}
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-20 py-16">
          <div className="grid gap-8">
            <Label>Investment Amount</Label>
            <div className="grid grid-cols-2 xsm:grid-cols-3 gap-8">
              {PRESET_AMOUNTS.map((preset) => (
                <button
                  key={preset}
                  type="button"
                  onClick={() => setAmount(preset)}
                  disabled={loading}
                  className={cn(
                    'cursor-pointer rounded-[12px] py-10 px-8 text-tiny font-medium border transition-all duration-200',
                    amount === preset
                      ? 'bg-primary border-primary text-white'
                      : 'bg-white/10 border-white/20 text-white hover:bg-white/20',
                    loading && 'opacity-50 cursor-not-allowed',
                  )}>
                  {formatPrice(preset)}
                </button>
              ))}
            </div>
          </div>
        </div>

        <DialogFooter className="flex items-center flex-wrap justify-between! w-full gap-20">
          <Button
            type="button"
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={loading}
            size="large"
            className="w-full xsm:w-auto">
            Cancel
          </Button>
          <Button
            type="button"
            onClick={handleInvest}
            disabled={loading || !amount}
            size="large"
            className="w-full xsm:w-auto">
            {loading ? 'Redirecting...' : 'Continue to Payment'}
          </Button>
        </DialogFooter>
        <p className="text-[10px] text-gray-2 text-center mt-8">
          Applicable taxes and fees will be added to your total at the time of
          processing.
        </p>
      </DialogContent>
    </Dialog>
  );
};

