import { cn } from 'lib/utils';
import { FC } from 'react';

interface Props {
  activeTab: 'setup' | 'returns' | 'transactions' | 'payments';
  onTabChange: (tab: 'setup' | 'returns' | 'transactions' | 'payments') => void;
  isNewProject: boolean;
}

const TABS: {
  label: string;
  value: 'setup' | 'returns' | 'transactions' | 'payments';
  showOnNewProject: boolean;
}[] = [
  {
    label: 'Setup Project',
    value: 'setup',
    showOnNewProject: true,
  },
  {
    label: 'Returns',
    value: 'returns',
    showOnNewProject: false,
  },
  {
    label: 'Transactions',
    value: 'transactions',
    showOnNewProject: false,
  },
  {
    label: 'Easy API',
    value: 'payments',
    showOnNewProject: false,
  },
];

export const Tabs: FC<Props> = ({ activeTab, onTabChange, isNewProject }) => {
  const visibleTabs = TABS.filter(
    (tab) => !isNewProject || tab.showOnNewProject,
  );

  return (
    <ul className="flex items-center mb-20 p-4 overflow-auto">
      {visibleTabs.map((tab) => (
        <li key={tab.value}>
          <button
            className={cn(
              'min-w-max px-16 py-8 text-small b-0 rounded-[20px] hover:scale-105 transition-all duration-300 ease-out cursor-pointer',
              activeTab === tab.value
                ? 'font-bold text-primary bg-black'
                : 'text-black bg-transparent',
            )}
            onClick={() => onTabChange(tab.value)}>
            {tab.label}
          </button>
        </li>
      ))}
    </ul>
  );
};

