'use server';

import { Routes } from 'const/Routes';
import { getPriceIdForTier, isTierDollars } from 'const/investment-tiers';
import { createEmbeddedCheckout } from 'lib/easy-api/checkout';
import { getProjectById } from 'lib/firebase/server-actions';
import { headers } from 'next/headers';

export type CreateCheckoutInput = {
  amount: number;
  userId: string;
  userEmail: string;
  projectId: string;
  projectName: string;
  projectType: ProjectType;
};

async function resolvePriceId(projectId: string, amount: number): Promise<string> {
  // 1. Try per-project price IDs stored on the Firestore document
  const project = await getProjectById(projectId);
  const perProjectPriceId = project?.easyApiPriceIds?.[String(amount)];
  if (perProjectPriceId) return perProjectPriceId;

  // 2. Fall back to global price IDs from env vars (set via `yarn setup:easy-api`)
  if (isTierDollars(amount)) {
    return getPriceIdForTier(amount);
  }

  throw new Error(
    `No price ID found for amount $${amount}. ` +
    `Run the Easy API setup for this project or configure the global price env vars.`,
  );
}

export async function createCheckoutAction(
  input: CreateCheckoutInput,
): Promise<string> {
  const { amount, userId, userEmail, projectId, projectName, projectType } = input;

  const priceId = await resolvePriceId(projectId, amount);

  const headersList = await headers();
  const host = headersList.get('host') ?? 'localhost:3000';
  const protocol = host.includes('localhost') ? 'http' : 'https';
  const baseUrl = `${protocol}://${host}`;

  const result = await createEmbeddedCheckout({
    line_items: [{ price_id: priceId, quantity: 1 }],
    mode: 'payment',
    success_url: `${baseUrl}${Routes.INVESTMENT_SUCCESS}?session_id={SESSION_ID}&projectId=${encodeURIComponent(projectId)}&projectName=${encodeURIComponent(projectName)}&amount=${amount}`,
    cancel_url: `${baseUrl}${Routes.INVESTMENT_CANCELLED}?projectId=${encodeURIComponent(projectId)}&projectName=${encodeURIComponent(projectName)}`,
    customer_email: userEmail,
    metadata: {
      userId,
      userEmail,
      projectId,
      projectName,
      projectType,
      amount: String(amount),
    },
  });

  if (!result.ok) {
    throw new Error('Failed to create checkout session. Please try again.');
  }

  return result.data.url;
}

