import { cn } from 'lib/utils';
import { FC } from 'react';

type AdminTab = 'setup' | 'returns' | 'transactions';

interface Props {
  activeTab: AdminTab;
  onTabChange: (tab: AdminTab) => void;
  isNewProject: boolean;
}

