import { createHmac, timingSafeEqual } from 'crypto';
import { FieldValue } from 'firebase-admin/firestore';
import { adminDb } from 'lib/firebase/admin';
import { NextResponse } from 'next/server';

type EasyApiPaymentUpdatedEvent = {
  type: string;
  data: {
    id: string;
    status: string;
    amount: number;
    currency: string;
    customer_email?: string;
    metadata?: {
      userId?: string;
      userEmail?: string;
      projectId?: string;
      projectName?: string;
      projectType?: string;
      amount?: string;
    };
  };
};

const SUCCEEDED_STATUSES = new Set(['succeeded', 'completed', 'paid']);

function verifySignature(rawBody: string, signature: string | null): boolean {
  const secret = process.env.WEBHOOK_SECRET;
  if (!secret || !signature) return false;

  const expected = `sha256=${createHmac('sha256', secret).update(rawBody).digest('hex')}`;
  try {
    return timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
  } catch {
    return false;
  }
}

export async function POST(request: Request) {
  const rawBody = await request.text();
  const signature = request.headers.get('x-easy-webhook-signature');

  if (!verifySignature(rawBody, signature)) {
    return NextResponse.json({ error: 'Invalid signature' }, { status: 401 });
  }

  let event: EasyApiPaymentUpdatedEvent;
  try {
    event = JSON.parse(rawBody);
  } catch {
    return NextResponse.json({ error: 'Invalid request body' }, { status: 400 });
  }

  if (
    event?.type !== 'payment.updated' ||
    !SUCCEEDED_STATUSES.has(event?.data?.status)
  ) {
    return NextResponse.json({ received: true });
  }

  const { metadata, id: paymentId } = event.data;

  if (!metadata?.userId || !metadata?.projectId || !metadata?.amount) {
    return NextResponse.json(
      { error: 'Missing required metadata fields: userId, projectId, amount' },
      { status: 400 },
    );
  }

  const amount = Number(metadata.amount);
  const projectType = (metadata.projectType ?? 'film') as ProjectType;

  const transaction: Transaction = {
    type: 'investment',
    projectId: metadata.projectId,
    projectName: metadata.projectName ?? '',
    projectType,
    amount,
    date: Date.now(),
    userId: metadata.userId,
    userEmail: metadata.userEmail ?? '',
    paymentId,
  };

  await adminDb.collection('transactions').add(transaction);

  await adminDb
    .collection('projects')
    .doc(metadata.projectId)
    .update({ moneyRaised: FieldValue.increment(amount) });

  return NextResponse.json({ received: true });
}

